import axiosTokenInstance from "../../service/network/axios";
import { UNREAD_COUNT_URL } from "src/api/endpoints/endpoints";
import {
  unreadCountRequest,
  unreadCountRequestError,
  unreadCountRequestSuccess,
} from "../slices/unreadCount";
import { getAuthToken } from "src/asyncstorage";

export const unreadCountAPI = () => async (dispatch: any | undefined) => {
  try {
    dispatch(unreadCountRequest());
    const token = await getAuthToken();
    axiosTokenInstance({
      method: "GET",
      url: UNREAD_COUNT_URL,
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`,
      },
    })
      .then((resp) => {
        dispatch(unreadCountRequestSuccess(resp?.data));
      })
      .catch((error) => {
        const _error = {
          data: error?.response?.status
            ? error?.response?.data?.message || error?.message
            : "Something went wrong. Try again!",
          status:
            error?.response?.data.statusCode || error?.response?.status || 500,
        };
        dispatch(unreadCountRequestError(_error));
      });
  } catch (error) {}
};
