import { PayloadAction, createSlice } from "@reduxjs/toolkit";
import { API_ERROR } from "../../typings/global";

interface expireCodeInterface {
  loading: boolean;
  response: any | undefined;
  error: API_ERROR | undefined;
}

const initialState: expireCodeInterface = {
  loading: false,
  response: undefined,
  error: undefined,
};

export const expireCodeSlice = createSlice({
  name: "expireCode",
  initialState,
  reducers: {
    expireCodeRequest(state) {
      state.loading = true;
    },
    expireCodeSuccess(state, action: PayloadAction<any>) {
      state.loading = false;
      state.response = action.payload;
      state.error = undefined;
    },
    expireCodeError(state, action: PayloadAction<API_ERROR>) {
      state.loading = false;
      state.error = action.payload;
      state.response = undefined;
    },
    expireCodeStateReset(state) {
      state.loading = false;
      state.error = undefined;
      state.response = undefined;
    },
  },
});

export const {
  expireCodeRequest,
  expireCodeSuccess,
  expireCodeError,
  expireCodeStateReset,
} = expireCodeSlice.actions;

export default expireCodeSlice.reducer;
